import{_ as o,l,o as a,c as n,v as i,p as s,x as t,d,i as p,S as b}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"卷积码与 Viterbi","description":"","frontmatter":{"title":"卷积码与 Viterbi","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/convolutional-viterbi.md","filePath":"cs/convolutional-viterbi.md","lastUpdated":1789023840000}'),c={name:"cs/convolutional-viterbi.md"};function h(m,e,u,_,V,E){const r=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=i('<h1 id="卷积码与-viterbi" tabindex="-1">卷积码与 Viterbi <a class="header-anchor" href="#卷积码与-viterbi" aria-label="Permalink to &quot;卷积码与 Viterbi&quot;">​</a></h1><div class="epigraph"><p>卷积码用移位寄存器把信息流编成网格上的路径；Viterbi 在网格上做最短路，按汉明或欧氏度量最大似然译码。</p><footer>—— 据 Viterbi, 1967；Forney；Lin and Costello 整理</footer></div><p>上一课<a href="/cs/reed-solomon">Reed–Solomon</a> 是块码：固定 \\(n\\)。缺口是<strong>流式</strong>：卷积码，记忆 \\(m\\) 的移位寄存器，网格（trellis）。Viterbi 动态规划找最可能路径。深空通信、旧移动通信的经典内码。不重写 RS 插值。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每拍吃 \\(k\\) 比特，吐 \\(n\\) 比特，依赖最近 \\(m\\) 拍。状态 \\(2^{m}\\) 量级。合法码字 = 网格从零状态走出的路径。噪声下观测偏离路径。Viterbi：对每个状态保留到达它的最优度量，向前递推——与主干最短路同一 DP 形状，边权是局部失真。</p><p>自由距离：两路径分叉再合并的最小重量，扮演 \\(d_{\\min}\\)。尾咬或归零处理块尾。</p><h3 id="不是隐马尔可夫的新课" tabindex="-1">不是隐马尔可夫的新课 <a class="header-anchor" href="#不是隐马尔可夫的新课" aria-label="Permalink to &quot;不是隐马尔可夫的新课&quot;">​</a></h3><p>网格译码与 HMM 的 Viterbi 同名同算法。本课对象是纠错码路径，不估计自然语言。度量可以是汉明（硬判决）或对数似然（软判决）。</p><p><span class="marginnote">Viterbi 1967。Forney 把卷积码讲成网格。Lin–Costello 教材。BCJR 后验概率译码是 Turbo 的组件，下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 \\(m=2\\) 的小网格，标一条信息路径。说明删边（硬判决）如何变成最短路。复杂度：时间 \\(\\times\\) 状态数，状态指数于记忆，故 \\(m\\) 不能很大——这是后课 LDPC 换稀疏图的原因。</p>',11)),(a(),s(b,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E7%A7%BB%E4%BD%8D%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20TRE%5B%22%E7%BD%91%E6%A0%BC%E8%B7%AF%E5%BE%84%22%5D%0A%20%20TRE%20--%3E%20VIT%5B%22Viterbi%20DP%22%5D%0A%20%20VIT%20--%3E%20ML%5B%22%E6%9C%80%E5%A4%A7%E4%BC%BC%E7%84%B6%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<p>主干<a href="/cs/interval-dp">区间 DP</a> / 最短路已有递推；这里格子是时间 \\(\\times\\) 寄存器状态。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>卷积码把冗余摊在时间上，适合流。级联：外 RS、内卷积，是 NASA 标准故事。达不到一般信道的容量极限（记忆短时），但实现成熟。Turbo 用两个卷积交织迭代，下一课。</p><p>生成多项式 \\(g_i(D)\\) 描述寄存器抽头。删余（puncturing）提高速率。软判决把边权改成 \\(-\\log p(y\\mid x)\\)，仍是 Viterbi。BCJR 算后验，Turbo 要用，本课 ML 足够。记忆 \\(m=6\\) 的 NASA 标准码是课堂史，不是容量极限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多项式生成元 \\(g(D)\\) 的全部代数，不证 Viterbi 最优。不引入 TCM 调制。后课默认：网格码用 Viterbi 最大似然。下一课近容量：LDPC 与 Turbo。</p><p>网格把最大似然变成最短路，状态数随记忆指数。这是短记忆实用、长记忆不可行的原因，也是下一课改用稀疏图迭代的动机。软判决只改边权。</p><p>上一课留下的缺口在本课收口；「卷积码与 Viterbi」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卷积码 = 移位寄存器 \\(\\to\\) 网格上的路径。</li><li>Viterbi：状态上的最短路 / 最大似然。</li><li>记忆短则状态少，距离与容量有限。</li><li>出处：Viterbi, 1967；Forney；Lin and Costello。</li></ul>',10))])}const f=o(c,[["render",h]]);export{A as __pageData,f as default};
